package com.orderflow.order;
import com.orderflow.contracts.Events.*;import jakarta.persistence.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.amqp.core.*;import org.springframework.amqp.rabbit.annotation.RabbitListener;import org.springframework.amqp.rabbit.core.RabbitTemplate;import org.springframework.amqp.support.converter.Jackson2JsonMessageConverter;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.context.annotation.*;import org.springframework.data.domain.*;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;import java.util.List;import java.util.ArrayList;
@SpringBootApplication public class OrderApplication{public static void main(String[]a){SpringApplication.run(OrderApplication.class,a);}@Bean Jackson2JsonMessageConverter json(){return new Jackson2JsonMessageConverter();}@Bean TopicExchange events(){return new TopicExchange("orderflow.events",true,false);}@Bean TopicExchange deadLetters(){return new TopicExchange("orderflow.dlx",true,false);}@Bean Queue orderDeadLetter(){return QueueBuilder.durable("orders.dead-letter").build();}@Bean Binding orderDlq(Queue orderDeadLetter,TopicExchange deadLetters){return BindingBuilder.bind(orderDeadLetter).to(deadLetters).with("#");}@Bean Queue invOk(){return QueueBuilder.durable("orders.inventory-reserved").deadLetterExchange("orderflow.dlx").build();}@Bean Queue invFail(){return QueueBuilder.durable("orders.inventory-failed").deadLetterExchange("orderflow.dlx").build();}@Bean Queue payOk(){return QueueBuilder.durable("orders.payment-succeeded").deadLetterExchange("orderflow.dlx").build();}@Bean Queue payFail(){return QueueBuilder.durable("orders.payment-failed").deadLetterExchange("orderflow.dlx").build();}@Bean Binding b1(Queue invOk,TopicExchange events){return BindingBuilder.bind(invOk).to(events).with("inventory.reserved");}@Bean Binding b2(Queue invFail,TopicExchange events){return BindingBuilder.bind(invFail).to(events).with("inventory.failed");}@Bean Binding b3(Queue payOk,TopicExchange events){return BindingBuilder.bind(payOk).to(events).with("payment.succeeded");}@Bean Binding b4(Queue payFail,TopicExchange events){return BindingBuilder.bind(payFail).to(events).with("payment.failed");}}
@Entity@Table(name="orders",schema="orders")class PurchaseOrder{@Id UUID id;@Column(name="user_id")UUID userId;@Enumerated(EnumType.STRING)Status status;BigDecimal total;@Column(name="created_at")Instant createdAt;@Column(name="updated_at")Instant updatedAt;@OneToMany(mappedBy="order",cascade=CascadeType.ALL,fetch=FetchType.EAGER)List<OrderItem>items=new ArrayList<>();protected PurchaseOrder(){}PurchaseOrder(UUID u,List<LineRequest>ls){id=UUID.randomUUID();userId=u;status=Status.PENDING;createdAt=updatedAt=Instant.now();for(var l:ls)items.add(new OrderItem(this,l));total=items.stream().map(i->i.unitPrice.multiply(BigDecimal.valueOf(i.quantity))).reduce(BigDecimal.ZERO,BigDecimal::add);}enum Status{PENDING,INVENTORY_RESERVED,CONFIRMED,CANCELLED}}
@Entity@Table(name="order_items",schema="orders")class OrderItem{@Id UUID id;@ManyToOne@JoinColumn(name="order_id")PurchaseOrder order;@Column(name="product_id")UUID productId;int quantity;@Column(name="unit_price")BigDecimal unitPrice;protected OrderItem(){}OrderItem(PurchaseOrder o,LineRequest l){id=UUID.randomUUID();order=o;productId=l.productId();quantity=l.quantity();unitPrice=l.unitPrice();}}
@Entity@Table(name="processed_events",schema="orders")class Seen{@Id@Column(name="event_id")UUID id;@Column(name="processed_at")Instant at=Instant.now();protected Seen(){}Seen(UUID i){id=i;}}
interface OrderRepo extends JpaRepository<PurchaseOrder,UUID>{Page<PurchaseOrder>findByUserId(UUID u,Pageable p);}interface SeenRepo extends JpaRepository<Seen,UUID>{}
record LineRequest(@NotNull UUID productId,@Min(1)int quantity,@NotNull@DecimalMin("0")BigDecimal unitPrice){}record CheckoutRequest(@NotNull UUID userId,@NotEmpty List<@Valid LineRequest>items){}
record OrderView(UUID id,UUID userId,String status,BigDecimal total,Instant createdAt){static OrderView of(PurchaseOrder o){return new OrderView(o.id,o.userId,o.status.name(),o.total,o.createdAt);}}
@Service class OrderService{private final OrderRepo orders;private final SeenRepo seen;private final RabbitTemplate rabbit;OrderService(OrderRepo o,SeenRepo s,RabbitTemplate r){orders=o;seen=s;rabbit=r;}@Transactional OrderView checkout(CheckoutRequest r){PurchaseOrder o=orders.save(new PurchaseOrder(r.userId(),r.items()));var lines=o.items.stream().map(i->new OrderLine(i.productId,i.quantity,i.unitPrice)).toList();rabbit.convertAndSend("orderflow.events","order.created",new OrderCreated(UUID.randomUUID(),o.id,o.userId,lines,o.total,Instant.now()));return OrderView.of(o);}@Transactional@RabbitListener(queues="orders.inventory-reserved")public void inventoryOk(InventoryReserved e){update(e.eventId(),e.orderId(),PurchaseOrder.Status.INVENTORY_RESERVED,null);}@Transactional@RabbitListener(queues="orders.inventory-failed")public void inventoryFail(InventoryReservationFailed e){update(e.eventId(),e.orderId(),PurchaseOrder.Status.CANCELLED,e.reason());}@Transactional@RabbitListener(queues="orders.payment-succeeded")public void paymentOk(PaymentSucceeded e){update(e.eventId(),e.orderId(),PurchaseOrder.Status.CONFIRMED,null);rabbit.convertAndSend("orderflow.events","order.confirmed",new OrderConfirmed(UUID.randomUUID(),e.orderId(),Instant.now()));}@Transactional@RabbitListener(queues="orders.payment-failed")public void paymentFail(PaymentFailed e){update(e.eventId(),e.orderId(),PurchaseOrder.Status.CANCELLED,e.reason());}void update(UUID event,UUID order,PurchaseOrder.Status status,String reason){if(seen.existsById(event))return;PurchaseOrder o=orders.findById(order).orElseThrow();o.status=status;o.updatedAt=Instant.now();seen.save(new Seen(event));if(status==PurchaseOrder.Status.CANCELLED)rabbit.convertAndSend("orderflow.events","order.cancelled",new OrderCancelled(UUID.randomUUID(),order,reason,Instant.now()));}@Transactional OrderView cancelByUser(UUID id,UUID caller,String role){PurchaseOrder o=orders.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!o.userId.equals(caller)&&!"ADMIN".equals(role))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"order belongs to another user");if(o.status==PurchaseOrder.Status.CANCELLED)return OrderView.of(o);if(o.status!=PurchaseOrder.Status.PENDING&&o.status!=PurchaseOrder.Status.INVENTORY_RESERVED)throw new ResponseStatusException(HttpStatus.CONFLICT,"confirmed orders require refund workflow");o.status=PurchaseOrder.Status.CANCELLED;o.updatedAt=Instant.now();rabbit.convertAndSend("orderflow.events","order.cancelled",new OrderCancelled(UUID.randomUUID(),id,"customer cancellation",Instant.now()));return OrderView.of(o);}Page<OrderView>history(UUID u,Pageable p){return orders.findByUserId(u,p).map(OrderView::of);}}
@RestController@RequestMapping("/api/orders")class OrderController{private final OrderService s;OrderController(OrderService s){this.s=s;}@PostMapping@ResponseStatus(HttpStatus.ACCEPTED)OrderView checkout(@RequestHeader("X-User-ID")UUID caller,@RequestHeader("X-User-Role")String role,@Valid@RequestBody CheckoutRequest r){authorize(r.userId(),caller,role);return s.checkout(r);}@GetMapping Page<OrderView>history(@RequestHeader("X-User-ID")UUID caller,@RequestHeader("X-User-Role")String role,@RequestParam UUID userId,Pageable p){authorize(userId,caller,role);return s.history(userId,p);}@PostMapping("/{id}/cancel")OrderView cancel(@PathVariable UUID id,@RequestHeader("X-User-ID")UUID caller,@RequestHeader("X-User-Role")String role){return s.cancelByUser(id,caller,role);}private void authorize(UUID requested,UUID caller,String role){if(!requested.equals(caller)&&!"ADMIN".equals(role))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"orders belong to another user");}}
